    if (exact.length === 1) return exact;
    var values = dictionary();
    Object.keys(fields).forEach(function (name) {
      var value = normalizedTemplateText(fields[name]);
      if (value) values[value] = true;
    });
    var named = characters.filter(function (character) {
      return values[normalize(character.get('name'))] && canControl(character, playerId);
    });
    if (named.length === 1) return named;
    var active = playerIsGM(playerId) && getObj('character', initState().activeCharacterId);
    if (active) return [active];
    var controlled = characters.filter(function (character) { return canControl(character, playerId); });
    return controlled.length === 1 ? controlled : [];
